head.b:skin:
/* 
THEME: Culinary Master Engine (Cinnamon & Charcoal Edition)
SYSTEM: Professional Recipe & Gastronomy Framework
*/
:root {
    --cinnamon: #d2691e;
    --charcoal: #2d2d2d;
    --cream: #fff9f0;
    --gold-leaf: #bc9c1a;
    --text-dark: #1a1a1a;
}
body {
    background-color: #f4f1ea;
    color: var(--text-dark);
    font-family: 'Playfair Display', serif;
    margin: 0; padding: 0;
}
.header-wrap {
    background: var(--charcoal);
    color: var(--gold-leaf);
    padding: 50px 20px;
    text-align: center;
    border-bottom: 4px solid var(--cinnamon);
}
.main-container {
    max-width: 850px;
    margin: -30px auto 60px;
    padding: 20px;
}
.culinary-card {
    background: var(--cream);
    border-radius: 8px;
    box-shadow: 0 15px 35px rgba(0,0,0,0.1);
    padding: 40px;
    margin-bottom: 25px;
    border: 1px solid #e0dcd0;
    position: relative;
}
.culinary-card::before {
    content: "";
    position: absolute;
    top: 10px; left: 10px; right: 10px; bottom: 10px;
    border: 1px solid #e0dcd0;
    pointer-events: none;
}
.input-group { margin-bottom: 25px; position: relative; z-index: 2; }
.input-group label {
    display: block;
    font-weight: bold;
    margin-bottom: 8px;
    color: var(--charcoal);
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 1.5px;
}
.input-group input, .input-group textarea {
    width: 100%;
    padding: 12px;
    border: 1px solid #ccc;
    border-radius: 0;
    font-family: 'Inter', sans-serif;
    box-sizing: border-box;
    background: #fff;
}
.input-group textarea { height: 100px; resize: vertical; }

.lang-options { display: flex; gap: 30px; margin-top: 10px; }
.lang-item { display: flex; align-items: center; cursor: pointer; font-weight: 600; color: var(--charcoal); }
.lang-item input { width: auto; margin-right: 10px; accent-color: var(--cinnamon); }

h2 { color: var(--cinnamon); text-align: center; margin-top: 0; font-style: italic; font-size: 28px; }

.copy-btn {
    background: var(--charcoal);
    color: var(--gold-leaf);
    border: none;
    padding: 18px;
    cursor: pointer;
    font-weight: bold;
    width: 100%;
    transition: 0.3s;
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 2px;
    z-index: 2;
    position: relative;
}
.copy-btn:hover { background: var(--cinnamon); color: #fff; }
footer { text-align: center; color: #777; padding: 20px; font-size: 12px; letter-spacing: 1px; }

body.script:
function copyPrompt() {
    var title = document.getElementById("inputTitle").value || "Dish of the Day";
    var notes = document.getElementById("inputNotes").value || "Use available seasonal ingredients.";

    var selectedLang = document.querySelector('input[name="lang"]:checked').value;
    var template = (selectedLang === 'id') ? 
                   document.getElementById("templateID").innerText : 
                   document.getElementById("templateEN").innerText;

    var finalPrompt = template.replace("[USER_TITLE]", title).replace("[USER_NOTES]", notes);

    var tempElem = document.createElement("textarea");
    tempElem.value = finalPrompt;
    document.body.appendChild(tempElem);
    tempElem.select();
    document.execCommand("copy");
    document.body.removeChild(tempElem);

    alert("👨‍🍳 Master Recipe Prompt (" + (selectedLang === 'id' ? 'Indonesia' : 'English') + ") copied! Ready for the kitchen.");
}
